#include <string>
#include <vector>

using namespace std;

class Solution {
public:
    bool canConvertString(string s, string t, int k) {
        if (s.size() != t.size()) return false;
        vector<int> count(26, 0);
        for (int i = 0; i < s.size(); ++i) {
            int diff = (t[i] - s[i] + 26) % 26;
            if (diff != 0) {
                int time = diff + 26 * count[diff]++;
                if (time > k) return false;
            }
        }
        return true;
    }
};
